DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 029", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "9456f994-b39d-5fd0-90a9-6aed85c01fab", "stem": "An athlete starts from home and runs continuously for two hours, gradually slowing down. Which graph best represents distance traveled d against elapsed time t?", "choices": [{"key": "A", "text": "Graph A"}, {"key": "B", "text": "Graph B"}, {"key": "C", "text": "Graph C"}, {"key": "D", "text": "Graph D"}], "type": "mcq", "correct": "D", "explanation": "Distance traveled starts at 0 and keeps increasing because the athlete is still moving. Its slope equals speed; as the runner slows down, this positive slope decreases. The graph must therefore start at the origin, rise, and be concave down. That is graph D. A shows constant speed, B increasing speed, and C a nonzero starting distance.", "topic": "Functions, Transformations & Graphs", "note": "Reunited the stem on page 168 with its four original graphs from HOA 019 page 17.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 168, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:HOA 025", "old_status": "partial_multi_question", "status": "ready", "question_id": "850b69cd-ab7d-5f73-bbbd-47fb4741e078", "stem": "Let x, y, and z be real numbers such that xy is a positive integer and xz is a negative integer. Which statements must be true? I. yz is positive. II. xy−xz is positive. III. xyz is negative.", "choices": [{"key": "A", "text": "I only"}, {"key": "B", "text": "II only"}, {"key": "C", "text": "III only"}, {"key": "D", "text": "I, II, and III"}], "type": "mcq", "correct": "B", "explanation": "Because x≠0, yz=(xy)(xz)/x² is negative, so I is false. A positive number minus a negative number is positive, so II is true. III need not hold: x=−1, y=−1, z=1 gives xy=1 and xz=−1 but xyz=1. Only II must be true.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Isolated complete Q15. The preceding triangle has no dimensions or angles sufficient to determine BC and remains excluded.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 21, "extra_sources": []}, {"id": "clean:HOA 027", "old_status": "duplicate", "status": "ready", "question_id": "5c220ec9-3c2c-5614-8b13-863a7699bc52", "stem": "Which point lies on both y=3x+9 and y=2x²+3x+1?", "choices": [{"key": "A", "text": "(2,3)"}, {"key": "B", "text": "(2,15)"}, {"key": "C", "text": "(−2,15)"}, {"key": "D", "text": "(−2,2)"}], "type": "mcq", "correct": "B", "explanation": "Equating y-values gives 3x+9=2x²+3x+1, so 2x²=8 and x=±2. The intersection points are (2,15) and (−2,3). Only (2,15) is listed.", "topic": "Functions, Transformations & Graphs", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 22, "extra_sources": []}, {"id": "clean:HOA 028", "old_status": "partial_multi_question", "status": "ready", "question_id": "e2773fd3-9586-5791-9122-f22704a3915f", "stem": "Hamad answers 80% of a 20-question section correctly and \\(\\frac{1250}{19}\\%\\) of a 38-question section correctly. How many questions does he answer correctly in total?", "choices": [{"key": "A", "text": "6"}, {"key": "B", "text": "41"}, {"key": "C", "text": "42"}, {"key": "D", "text": "58"}], "type": "mcq", "correct": "B", "explanation": "The first section contributes 20(0.8)=16. The second contributes 38·(1250/19)/100=25. The total is 16+25=41.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 23, "extra_sources": [], "parts": [{"label": "Q3", "question_id": "f769d61f-049a-5acd-b608-924670444b5b", "stem": "If −2x+5y=39 and 3x=−4y+45, what is 2x+7y?", "choices": [{"key": "A", "text": "−57"}, {"key": "B", "text": "15"}, {"key": "C", "text": "39"}, {"key": "D", "text": "69"}], "type": "mcq", "correct": "D", "explanation": "Rewrite the second equation as 3x+4y=45. Multiply the first by 3 and the second by 2, then add: 23y=207, so y=9. Substitution gives x=3. Thus 2x+7y=6+63=69.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:HOA 030", "old_status": "duplicate", "status": "ready", "question_id": "5197fbd4-e71b-5337-a618-ae301df0310b", "stem": "If \\(4x+14y=-7\\), what is \\(-x-\\frac72y\\)?", "choices": [{"key": "A", "text": "\\(-7/4\\)"}, {"key": "B", "text": "\\(7/4\\)"}, {"key": "C", "text": "\\(-7/2\\)"}, {"key": "D", "text": "\\(7/2\\)"}], "type": "mcq", "correct": "B", "explanation": "Multiply the entire given equation by −1/4. Its left side becomes −x−(7/2)y and its right side becomes 7/4, the required value.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 24, "extra_sources": []}, {"id": "clean:HOA 031", "old_status": "duplicate", "status": "ready", "question_id": "3940b947-8007-5c5b-a803-20a8fcf4e7b0", "stem": "Which point satisfies −3<2x−y≤14?", "choices": [{"key": "A", "text": "(0,3)"}, {"key": "B", "text": "(4,−8)"}, {"key": "C", "text": "(3,4)"}, {"key": "D", "text": "(4,12)"}], "type": "mcq", "correct": "C", "explanation": "Evaluate 2x−y for the choices: −3, 16, 2, and −4, respectively. Only 2 lies in the interval (−3,14]. The strict lower inequality excludes −3.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 24, "extra_sources": []}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
